// Side Effects & Sequence Points (C Standard)

int i = 5;

// Undefined Behavior (UB): i is modified (i++)
// and accessed (i) without an intervening sequence point.
// Operands of binary '+' are unsequenced.
int result_ub = i++ + i;

// Sequence Points occur at: Statement end (;),
// Logical operators (&&, ||), Ternary (?:), Comma (,) operator.

// Precedence Example: * higher than +
int x = 10, y = 5, z = 2;
int result_prec = x + y * z; // Grouped as x + (y * z) -> 20

// Associativity Example: Assignment is Right-to-Left
int v, w;
v = w = 100; // Evaluated as v = (w = 100);
